} ssl_connection_t;

int ssl_init(void);
ssl_connection_t* ssl_connect(const char *hostname, int port);
int ssl_send(ssl_connection_t *conn, const char *data, int length);
int ssl_receive(ssl_connection_t *conn, char *buffer, int buffer_size);
void ssl_disconnect(ssl_connection_t *conn);
void ssl_cleanup(void);
void print_ssl_errors(void);

void print_ssl_errors(void) {
    ERR_print_errors_fp(stderr);
}

int ssl_init(void) {
#if OPENSSL_VERSION_NUMBER < 0x10100000L
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();
#endif
    return 0;
}

ssl_connection_t* ssl_connect(const char *hostname, int port) {
    struct hostent *host;
    struct sockaddr_in addr;
    ssl_connection_t *conn;

    conn = (ssl_connection_t*)malloc(sizeof(ssl_connection_t));
    if (!conn) return NULL;

    memset(conn, 0, sizeof(ssl_connection_t));
    conn->sockfd = -1;

    host = gethostbyname(hostname);
    if (!host) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", hostname);
        free(conn);
        return NULL;
    }

    conn->sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->sockfd < 0) {
        perror("socket");
        free(conn);
        return NULL;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    memcpy(&addr.sin_addr.s_addr, host->h_addr, host->h_length);

    if (connect(conn->sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(conn->sockfd);
        free(conn);
        return NULL;
    }

    conn->ctx = SSL_CTX_new(TLS_client_method());
    if (!conn->ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        print_ssl_errors();
        close(conn->sockfd);
        free(conn);
        return NULL;
    }

    SSL_CTX_set_verify(conn->ctx, SSL_VERIFY_PEER, NULL);
    SSL_CTX_set_default_verify_paths(conn->ctx);

    conn->ssl = SSL_new(conn->ctx);
    if (!conn->ssl) {
        fprintf(stderr, "Failed to create SSL object\n");
        print_ssl_errors();
        SSL_CTX_free(conn->ctx);
        close(conn->sockfd);
        free(conn);
        return NULL;
    }

    SSL_set_fd(conn->ssl, conn->sockfd);

    if (SSL_set_tlsext_host_name(conn->ssl, hostname) != 1) {
        fprintf(stderr, "Failed to set SNI hostname\n");
    }

    if (SSL_connect(conn->ssl) != 1) {
        fprintf(stderr, "SSL handshake failed\n");
        print_ssl_errors();
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        close(conn->sockfd);
        free(conn);
        return NULL;
    }

    return conn;
}

int ssl_send(ssl_connection_t *conn, const char *data, int length) {
    if (!conn || !conn->ssl) return -1;
    return SSL_write(conn->ssl, data, length);
}

int ssl_receive(ssl_connection_t *conn, char *buffer, int buffer_size) {
    if (!conn || !conn->ssl) return -1;
    int ret = SSL_read(conn->ssl, buffer, buffer_size - 1);
    if (ret > 0) {
        buffer[ret] = '\0';
    }
    return ret;
}

void ssl_disconnect(ssl_connection_t *conn) {
    if (!conn) return;

    if (conn->ssl) {
        SSL_shutdown(conn->ssl);
        SSL_free(conn->ssl);
    }

    if (conn->ctx) {
        SSL_CTX_free(conn->ctx);
    }

    if (conn->sockfd >= 0) {
        close(conn->sockfd);
    }

    free(conn);
}

void ssl_cleanup(void) {
#if OPENSSL_VERSION_NUMBER < 0x10100000L
    EVP_cleanup();
    ERR_free_strings();
#endif
}

int main(int argc, char *argv[]) {
    const char *hostname;
    int port;
    ssl_connection_t *conn;
    char buffer[4096];
    int bytes;
    char request[1024];

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <hostname> <port>\n", argv[0]);
        return 1;
    }

    hostname = argv[1];
    port = atoi(argv[2]);

    ssl_init();

    conn = ssl_connect(hostname, port);
    if (!conn) {
        fprintf(stderr, "Failed to establish secure connection to %s:%d\n", hostname, port);
        ssl_cleanup();
        return 1;
    }

    printf("Secure connection established to %s:%d\n", hostname, port);
    printf("Protocol: %s\n", SSL_get_version(conn->ssl));
    printf("Cipher: %s\n", SSL_get_cipher(conn->ssl));

    snprintf(request, sizeof(request),
             "GET / HTTP/1.1\r\nHost: %s\r\nUser-Agent: ssl-client/1.0\r\nConnection: close\r\n\r\n",
             hostname);

    if (ssl_send(conn, request, strlen(request)) <= 0) {
        fprintf(stderr, "Failed to send request\n");
        print_ssl_errors();
        ssl_disconnect(conn);
        ssl_cleanup();
        return 1;
    }

    while ((bytes = ssl_receive(conn, buffer, sizeof(buffer))) > 0) {
        fwrite(buffer, 1, bytes, stdout);
    }

    if (bytes < 0) {
        fprintf(stderr, "\nError receiving data\n");
        print_ssl_errors();
    }

    ssl_disconnect(conn);
    ssl_cleanup();

    return 0;
}
